{
  "name": "KisaanMate - Beginner Farming Assistant",
  "description": "An AI-powered guide for first-time farmers in India, focusing on organic practices, risk management, and step-by-step planning.",
  "requestFramePermissions": [
    "camera",
    "microphone"
  ]
}

export type Language = 'English' | 'Hindi' | 'Tamil' | 'Telugu' | 'Kannada';

export interface UserProfile {
  name: string;
  language: Language;
  goal: 'Income' | 'Hobby' | 'Organic Food' | 'Agri-tourism' | 'Land Productivity';
  waterSource: 'Borewell' | 'Canal' | 'Rain' | 'Unsure';
  involvement: 'Daily' | 'Weekend' | 'Hired Help' | 'Hands-off';
  budget: string; // Range string
  location: string;
  landSize: string;
  experienceLevel: 'None' | 'Beginner';
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'model';
  text: string;
  image?: string; // base64
  isError?: boolean;
}

export interface CropRecommendation {
  id: string;
  name: string;
  suitability: number; // 0-100
  reason: string;
  riskLevel: 'Low' | 'Medium' | 'High';
  costEstimate: string;
  duration: string;
}

export interface Task {
  id: string;
  week: number;
  title: string;
  description: string;
  status: 'pending' | 'completed';
}

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { UserProfile, ChatMessage } from "../types";

// Initialize Gemini Client
// CRITICAL: process.env.API_KEY is injected by the runtime environment.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const getSystemInstruction = (profile: UserProfile): string => {
  return `
You are KisaanMate, an empathetic, practical farming assistant for a FIRST-TIME farmer in India.
User Context:
- Name: ${profile.name}
- Location: ${profile.location}
- Goal: ${profile.goal}
- Water: ${profile.waterSource}
- Involvement: ${profile.involvement}
- Budget: ${profile.budget}
- Language Preference: ${profile.language} (Reply in English but use simple terms, unless asked to switch).

Your Core Rules:
1. **Safety First:** Prioritize organic, eco-friendly methods. Avoid chemical pesticides unless absolutely necessary (and warn about risks).
2. **Beginner Focus:** No jargon. Explain "Why". Suggest crops that are forgiving to mistakes.
3. **Risk Management:** Never promise profits. Use words like "estimated", "potential".
4. **Tone:** Calm, supportive, non-judgmental.
5. **Structure:** Use bullet points. Keep advice actionable.

If the user uploads an image of soil, say "Based on visual cues..." and never claim 100% scientific accuracy.
If the user asks about pests, suggest neem oil, sticky traps, or companion planting first.
`;
};

export const sendMessageToGemini = async (
  message: string,
  history: ChatMessage[],
  userProfile: UserProfile,
  image?: string
): Promise<string> => {
  try {
    const systemInstruction = getSystemInstruction(userProfile);

    // Select model based on whether image is present
    // Using gemini-2.5-flash-image for multimodal, gemini-3-flash-preview for text speed/logic
    const modelName = image ? 'gemini-2.5-flash-image' : 'gemini-3-flash-preview';

    let contents: any = {};

    if (image) {
      // Clean base64 string if it has prefix
      const base64Data = image.split(',')[1] || image;

      contents = {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg', // Assuming JPEG for simplicity in this demo context
              data: base64Data
            }
          },
          { text: message || "Analyze this image in the context of farming." }
        ]
      };
    } else {
      contents = { parts: [{ text: message }] };
    }

    // Convert history for context (simplified for this demo, usually we'd pass full history object)
    // Here we act as if it's a fresh generation with system instruction context to save tokens/complexity in this demo structure
    // but effectively, we prepend the context.

    const response: GenerateContentResponse = await ai.models.generateContent({
      model: modelName,
      contents: contents,
      config: {
        systemInstruction: systemInstruction,
        temperature: 0.7, // Balanced creativity and safety
      }
    });

    return response.text || "I apologize, I couldn't generate a response at this moment. Please try again.";

  } catch (error) {
    console.error("Gemini API Error:", error);
    return "I'm having trouble connecting to the field experts (server error). Please check your connection and try again.";
  }
};

export const generatePlanAnalysis = async (userProfile: UserProfile): Promise<string> => {
  try {
    const prompt = `Create a brief summary for my farming plan. I have ${userProfile.landSize} of land in ${userProfile.location}. Water: ${userProfile.waterSource}. Goal: ${userProfile.goal}. Budget: ${userProfile.budget}. Suggest 2 best beginner crops and 1 major risk to watch out for.`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts: [{ text: prompt }] },
      config: {
        systemInstruction: getSystemInstruction(userProfile)
      }
    });

    return response.text || "Could not generate plan.";
  } catch (e) {
    return "Plan generation unavailable.";
  }
}

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'outline' | 'danger';
  fullWidth?: boolean;
}

const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  fullWidth = false, 
  className = '', 
  ...props 
}) => {
  const baseStyles = "px-4 py-3 rounded-xl font-medium transition-all duration-200 flex items-center justify-center gap-2 active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed";

  const variants = {
    primary: "bg-green-600 text-white hover:bg-green-700 shadow-lg shadow-green-200",
    secondary: "bg-amber-100 text-amber-900 hover:bg-amber-200",
    outline: "border-2 border-gray-200 text-gray-700 hover:border-green-600 hover:text-green-600 bg-transparent",
    danger: "bg-red-50 text-red-600 hover:bg-red-100"
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${fullWidth ? 'w-full' : ''} ${className}`}
      {...props}
    >
      {children}
    </button>
  );
};

export default Button;

import React, { useState } from 'react';
import { UserProfile } from '../types';
import Button from './Button';
import { Sprout, Droplets, MapPin, IndianRupee, Clock } from 'lucide-react';

interface OnboardingProps {
  onComplete: (profile: UserProfile) => void;
}

const Onboarding: React.FC<OnboardingProps> = ({ onComplete }) => {
  const [step, setStep] = useState(1);
  const [profile, setProfile] = useState<Partial<UserProfile>>({
    experienceLevel: 'Beginner'
  });

  const handleNext = () => setStep(s => s + 1);

  const updateProfile = (key: keyof UserProfile, value: any) => {
    setProfile(prev => ({ ...prev, [key]: value }));
  };

  const finish = () => {
    if (profile.name && profile.location) {
      onComplete(profile as UserProfile);
    }
  };

  return (
    <div className="min-h-screen bg-white flex flex-col items-center justify-center p-6 max-w-lg mx-auto">
      <div className="w-full mb-8">
        <div className="flex justify-between mb-4">
           {[1, 2, 3, 4].map(i => (
             <div key={i} className={`h-2 rounded-full flex-1 mx-1 ${i <= step ? 'bg-green-600' : 'bg-gray-200'}`} />
           ))}
        </div>
        <h1 className="text-2xl font-bold text-gray-800 mb-2">
          {step === 1 && "Welcome, Farmer!"}
          {step === 2 && "Your Land & Water"}
          {step === 3 && "Goals & Budget"}
          {step === 4 && "Final Details"}
        </h1>
        <p className="text-gray-500">
          {step === 1 && "Let's get to know you to build the perfect plan."}
          {step === 2 && "Understanding your resources is key to success."}
          {step === 3 && "What do you want to achieve?"}
          {step === 4 && "Almost ready to start planting."}
        </p>
      </div>

      <div className="w-full flex-1 overflow-y-auto pb-4">
        {step === 1 && (
          <div className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Your Name</label>
              <input 
                type="text" 
                className="w-full p-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-green-500 outline-none"
                placeholder="e.g. Rahul Kumar"
                value={profile.name || ''}
                onChange={(e) => updateProfile('name', e.target.value)}
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Preferred Language</label>
              <select 
                className="w-full p-3 border border-gray-300 rounded-xl bg-white"
                value={profile.language || ''}
                onChange={(e) => updateProfile('language', e.target.value)}
              >
                <option value="">Select Language</option>
                <option value="English">English</option>
                <option value="Hindi">Hindi</option>
                <option value="Tamil">Tamil</option>
                <option value="Telugu">Telugu</option>
                <option value="Kannada">Kannada</option>
              </select>
            </div>
          </div>
        )}

        {step === 2 && (
          <div className="space-y-4">
             <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Location (State/District)</label>
              <div className="relative">
                <MapPin className="absolute left-3 top-3.5 h-5 w-5 text-gray-400" />
                <input 
                  type="text" 
                  className="w-full pl-10 p-3 border border-gray-300 rounded-xl"
                  placeholder="e.g. Pune, Maharashtra"
                  value={profile.location || ''}
                  onChange={(e) => updateProfile('location', e.target.value)}
                />
              </div>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Water Source</label>
              <div className="grid grid-cols-2 gap-3">
                {['Borewell', 'Canal', 'Rain', 'Unsure'].map((opt) => (
                  <button
                    key={opt}
                    onClick={() => updateProfile('waterSource', opt)}
                    className={`p-3 rounded-xl border text-sm font-medium transition-colors ${
                      profile.waterSource === opt 
                      ? 'border-green-600 bg-green-50 text-green-700' 
                      : 'border-gray-200 text-gray-600 hover:bg-gray-50'
                    }`}
                  >
                    {opt}
                  </button>
                ))}
              </div>
            </div>
            <div>
               <label className="block text-sm font-medium text-gray-700 mb-1">Total Land Size</label>
               <input 
                type="text" 
                className="w-full p-3 border border-gray-300 rounded-xl"
                placeholder="e.g. 2 Acres"
                value={profile.landSize || ''}
                onChange={(e) => updateProfile('landSize', e.target.value)}
              />
            </div>
          </div>
        )}

        {step === 3 && (
          <div className="space-y-4">
             <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Primary Goal</label>
              <select 
                className="w-full p-3 border border-gray-300 rounded-xl bg-white"
                value={profile.goal || ''}
                onChange={(e) => updateProfile('goal', e.target.value)}
              >
                <option value="">Select Goal</option>
                <option value="Income">Income (Profit focus)</option>
                <option value="Hobby">Hobby / Relaxation</option>
                <option value="Organic Food">Home Consumption</option>
                <option value="Land Productivity">Keep Land Active</option>
              </select>
            </div>
             <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Budget Range (₹)</label>
              <div className="relative">
                <IndianRupee className="absolute left-3 top-3.5 h-5 w-5 text-gray-400" />
                <input 
                  type="text" 
                  className="w-full pl-10 p-3 border border-gray-300 rounded-xl"
                  placeholder="e.g. 50,000 - 1 Lakh"
                  value={profile.budget || ''}
                  onChange={(e) => updateProfile('budget', e.target.value)}
                />
              </div>
            </div>
          </div>
        )}

        {step === 4 && (
          <div className="space-y-4">
             <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">How involved can you be?</label>
              <div className="grid grid-cols-1 gap-3">
                {[
                  { id: 'Daily', label: 'Daily (Full-time)', desc: 'Best for vegetables/flowers' },
                  { id: 'Weekend', label: 'Weekend Farmer', desc: 'Good for trees/hardy crops' },
                  { id: 'Hired Help', label: 'Dependent on Labor', desc: 'Needs good management' },
                ].map((opt) => (
                  <button
                    key={opt.id}
                    onClick={() => updateProfile('involvement', opt.id)}
                    className={`p-4 rounded-xl border text-left transition-colors ${
                      profile.involvement === opt.id 
                      ? 'border-green-600 bg-green-50' 
                      : 'border-gray-200 hover:bg-gray-50'
                    }`}
                  >
                    <div className={`font-semibold ${profile.involvement === opt.id ? 'text-green-800' : 'text-gray-800'}`}>{opt.label}</div>
                    <div className="text-xs text-gray-500">{opt.desc}</div>
                  </button>
                ))}
              </div>
            </div>
          </div>
        )}
      </div>

      <div className="w-full pt-4">
        {step < 4 ? (
          <Button 
            fullWidth 
            onClick={handleNext} 
            disabled={
              (step === 1 && (!profile.name || !profile.language)) ||
              (step === 2 && (!profile.location || !profile.waterSource)) ||
              (step === 3 && (!profile.goal || !profile.budget))
            }
          >
            Next Step
          </Button>
        ) : (
          <Button 
            fullWidth 
            onClick={finish}
            disabled={!profile.involvement}
          >
            Create My Farm Plan
          </Button>
        )}
      </div>
    </div>
  );
};

export default Onboarding;

import React, { useState, useRef, useEffect } from 'react';
import { Send, Image as ImageIcon, X, Loader2, Sprout } from 'lucide-react';
import { UserProfile, ChatMessage } from '../types';
import { sendMessageToGemini } from '../services/geminiService';
import Button from './Button';

interface AIChatProps {
  userProfile: UserProfile;
}

const AIChat: React.FC<AIChatProps> = ({ userProfile }) => {
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<ChatMessage[]>([
    {
      id: 'welcome',
      role: 'model',
      text: `Namaste ${userProfile.name}! I am your farming assistant. I can help you identify pests, analyze soil from photos, or answer simple questions. How can I help today?`
    }
  ]);
  const [isLoading, setIsLoading] = useState(false);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(scrollToBottom, [messages]);

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSend = async () => {
    if ((!input.trim() && !selectedImage) || isLoading) return;

    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      text: input,
      image: selectedImage || undefined
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setSelectedImage(null);
    setIsLoading(true);

    const responseText = await sendMessageToGemini(
      userMsg.text, 
      messages, 
      userProfile, 
      userMsg.image
    );

    const modelMsg: ChatMessage = {
      id: (Date.now() + 1).toString(),
      role: 'model',
      text: responseText
    };

    setMessages(prev => [...prev, modelMsg]);
    setIsLoading(false);
  };

  return (
    <div className="flex flex-col h-[calc(100vh-80px)] bg-gray-50">
      {/* Header */}
      <div className="bg-white p-4 border-b border-gray-200 flex items-center gap-3 sticky top-0 z-10">
        <div className="w-10 h-10 bg-green-100 rounded-full flex items-center justify-center">
          <Sprout className="text-green-600 w-6 h-6" />
        </div>
        <div>
          <h2 className="font-semibold text-gray-800">KisaanMate Assistant</h2>
          <p className="text-xs text-gray-500">Always Organic • Beginner Friendly</p>
        </div>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {messages.map((msg) => (
          <div 
            key={msg.id} 
            className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
          >
            <div 
              className={`max-w-[85%] rounded-2xl p-4 shadow-sm ${
                msg.role === 'user' 
                ? 'bg-green-600 text-white rounded-br-none' 
                : 'bg-white text-gray-800 border border-gray-100 rounded-bl-none'
              }`}
            >
              {msg.image && (
                <img 
                  src={msg.image} 
                  alt="User upload" 
                  className="w-full h-48 object-cover rounded-lg mb-3 border border-white/20" 
                />
              )}
              <div className="whitespace-pre-wrap text-sm leading-relaxed">
                {msg.text}
              </div>
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-white p-4 rounded-2xl rounded-bl-none border border-gray-100 flex items-center gap-2">
              <Loader2 className="w-4 h-4 animate-spin text-green-600" />
              <span className="text-sm text-gray-500">Thinking...</span>
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Input Area */}
      <div className="bg-white border-t border-gray-200 p-3">
        {selectedImage && (
          <div className="mb-2 relative inline-block">
            <img src={selectedImage} alt="Preview" className="h-20 w-20 object-cover rounded-lg border border-gray-200" />
            <button 
              onClick={() => setSelectedImage(null)}
              className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full p-1 shadow-md hover:bg-red-600"
            >
              <X className="w-3 h-3" />
            </button>
          </div>
        )}
        <div className="flex items-center gap-2">
          <input 
            type="file" 
            accept="image/*" 
            className="hidden" 
            ref={fileInputRef}
            onChange={handleImageSelect}
          />
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="p-3 text-gray-500 hover:bg-gray-100 rounded-full transition-colors"
            title="Upload photo of soil or plant"
          >
            <ImageIcon className="w-6 h-6" />
          </button>
          <div className="flex-1 relative">
            <textarea
              className="w-full border border-gray-300 rounded-2xl py-3 px-4 pr-10 focus:ring-2 focus:ring-green-500 outline-none resize-none scrollbar-hide bg-gray-50 focus:bg-white transition-colors"
              rows={1}
              placeholder="Ask about crops, pests, or send a photo..."
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter' && !e.shiftKey) {
                  e.preventDefault();
                  handleSend();
                }
              }}
            />
          </div>
          <Button 
            onClick={handleSend} 
            disabled={(!input && !selectedImage) || isLoading}
            className="!rounded-full !px-3 !py-3"
          >
            <Send className="w-5 h-5" />
          </Button>
        </div>
      </div>
    </div>
  );
};

export default AIChat;

import React, { useState, useEffect } from 'react';
import { UserProfile } from '../types';
import { PieChart, Pie, Cell, ResponsiveContainer, Legend, Tooltip } from 'recharts';
import { CheckCircle2, Circle, AlertCircle } from 'lucide-react';
import { generatePlanAnalysis } from '../services/geminiService';

interface MyPlanProps {
  userProfile: UserProfile;
}

const MyPlan: React.FC<MyPlanProps> = ({ userProfile }) => {
  const [activeTab, setActiveTab] = useState<'tasks' | 'economics'>('tasks');
