  useEffect(() => {
    generatePlanAnalysis(userProfile).then(setAiSummary);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Mock data adapted to user choices ideally, but static for demo structure
  const tasks = [
    { id: '1', week: 1, title: 'Soil Preparation', status: 'completed', desc: 'Clear weeds and plow the land lightly.' },
    { id: '2', week: 1, title: 'Soil Testing', status: 'pending', desc: 'Take a sample from 5 spots and mix.' },
    { id: '3', week: 2, title: 'Purchase Seeds', status: 'pending', desc: 'Buy organic seeds for Spinach/Fenugreek.' },
    { id: '4', week: 2, title: 'Basic Irrigation', status: 'pending', desc: 'Set up drip lines if possible.' },
  ];

  const costData = [
    { name: 'Seeds', value: 2000 },
    { name: 'Fertilizer (Organic)', value: 4000 },
    { name: 'Labor/Prep', value: 5000 },
    { name: 'Water/Misc', value: 3000 },
