  return (
    <div className="flex flex-col h-full bg-gray-50 pb-20">
      <div className="bg-white p-4 border-b border-gray-200">
        <h2 className="text-xl font-bold text-gray-800">Your Farm Plan</h2>
        <div className="flex gap-2 mt-4">
          <button 
            onClick={() => setActiveTab('tasks')}
            className={`flex-1 py-2 text-sm font-medium rounded-lg transition-colors ${activeTab === 'tasks' ? 'bg-green-100 text-green-700' : 'text-gray-500'}`}
