            Costs & Risks
          </button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-4">
        {/* AI Insight Box */}
        <div className="bg-gradient-to-r from-green-600 to-green-700 rounded-xl p-4 text-white mb-6 shadow-lg shadow-green-200">
          <h3 className="font-semibold text-sm flex items-center gap-2 mb-2">
            <span className="bg-white/20 p-1 rounded">AI</span> 
            Plan Analysis
          </h3>
          <p className="text-sm opacity-95 leading-relaxed">
            {aiSummary}
          </p>
        </div>

        {activeTab === 'tasks' ? (
          <div className="space-y-4">
            <h3 className="font-bold text-gray-700">Next 4 Weeks</h3>
            {tasks.map((task) => (
              <div key={task.id} className="bg-white p-4 rounded-xl border border-gray-200 flex gap-4 items-start">
                <button className="mt-1">
                  {task.status === 'completed' 
                    ? <CheckCircle2 className="text-green-600 w-6 h-6" /> 
                    : <Circle className="text-gray-300 w-6 h-6" />
                  }
                </button>
                <div>
                  <div className="flex items-center gap-2 mb-1">
                    <span className="bg-gray-100 text-gray-600 text-[10px] px-2 py-0.5 rounded-full font-bold">WEEK {task.week}</span>
                    <h4 className={`font-semibold ${task.status === 'completed' ? 'text-gray-400 line-through' : 'text-gray-800'}`}>
                      {task.title}
                    </h4>
                  </div>
                  <p className="text-sm text-gray-500">{task.desc}</p>
                </div>
              </div>
            ))}
            <div className="text-center p-4">
              <button className="text-green-600 font-medium text-sm">View Full Calendar</button>
            </div>
          </div>
        ) : (
