import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { UserProfile, ChatMessage, SoilType, MoistureLevel } from "../types";

// Initialize Gemini Client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const getSystemInstruction = (profile: UserProfile): string => {
  return `
You are KisaanMate, an empathetic, practical farming assistant for a FIRST-TIME farmer in India.
User Context:
- Name: ${profile.name}
- Location: ${profile.location}
- Goal: ${profile.goal}
- Water: ${profile.waterSource}
- Involvement: ${profile.involvement}
- Budget: ${profile.budget}
- Language Preference: ${profile.language} (Reply in English but use simple terms, unless asked to switch).

Your Core Rules:
1. **Safety First:** Prioritize organic, eco-friendly methods. Avoid chemical pesticides unless absolutely necessary (and warn about risks).
2. **Beginner Focus:** No jargon. Explain "Why". Suggest crops that are forgiving to mistakes.
3. **Risk Management:** Never promise profits. Use words like "estimated", "potential".
4. **Tone:** Calm, supportive, non-judgmental.
5. **Structure:** Use bullet points. Keep advice actionable.

If the user uploads an image of soil, say "Based on visual cues..." and never claim 100% scientific accuracy.
If the user asks about pests, suggest neem oil, sticky traps, or companion planting first.
`;
};

export const sendMessageToGemini = async (
  message: string,
  history: ChatMessage[],
  userProfile: UserProfile,
  image?: string
): Promise<string> => {
  try {
    const systemInstruction = getSystemInstruction(userProfile);
    const modelName = image ? 'gemini-2.5-flash-image' : 'gemini-3-flash-preview';

    let contents: any = {};

    if (image) {
      const base64Data = image.split(',')[1] || image;
      contents = {
        parts: [
          { inlineData: { mimeType: 'image/jpeg', data: base64Data } },
          { text: message || "Analyze this image in the context of farming." }
        ]
      };
    } else {
      contents = { parts: [{ text: message }] };
    }

    const response: GenerateContentResponse = await ai.models.generateContent({
      model: modelName,
      contents: contents,
      config: {
        systemInstruction: systemInstruction,
        temperature: 0.7,
      }
    });

    return response.text || "I apologize, I couldn't generate a response at this moment. Please try again.";

  } catch (error) {
    console.error("Gemini API Error:", error);
    return "I'm having trouble connecting to the field experts (server error). Please check your connection and try again.";
  }
};

export const generatePlanAnalysis = async (userProfile: UserProfile): Promise<string> => {
  try {
    const prompt = `Create a brief summary for my farming plan. I have ${userProfile.landSize} of land in ${userProfile.location}. Water: ${userProfile.waterSource}. Goal: ${userProfile.goal}. Budget: ${userProfile.budget}. Suggest 2 best beginner crops and 1 major risk to watch out for.`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts: [{ text: prompt }] },
      config: {
        systemInstruction: getSystemInstruction(userProfile)
      }
    });

    return response.text || "Could not generate plan.";
  } catch (e) {
    return "Plan generation unavailable.";
  }
}

export const getCropRecommendations = async (
  userProfile: UserProfile,
  soilType: SoilType,
  moisture: MoistureLevel,
  soilImage?: string
): Promise<string> => {
  const prompt = `
  Context: User is a beginner farmer in ${userProfile.location}.
  Soil Type Provided: ${soilType}.
  Moisture Level: ${moisture}.
  Water Source: ${userProfile.waterSource}.

  Task: Suggest 3 suitable crops for beginners.
  If an image is provided, analyze it visually to confirm soil type (say "Based on visual cues...").

  Output format:
  1. [Crop Name]: [Why it is suitable] (Risk: Low/Med/High)

  Keep it simple.
  `;

  return sendMessageToGemini(prompt, [], userProfile, soilImage);
};

export const getDashboardInsights = async (userProfile: UserProfile): Promise<string> => {
  const prompt = `Give me 1 short, actionable farming tip based on ${userProfile.location} weather and beginner level. Max 20 words.`;
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts: [{ text: prompt }] },
      config: { systemInstruction: getSystemInstruction(userProfile) }
    });
    return response.text || "Check soil moisture daily.";
  } catch (e) {
    return "Keep your farm clean and weed-free.";
  }
};

export const getRiskAssessment = async (userProfile: UserProfile): Promise<string> => {
  const prompt = `
  Analyze risk for this farmer:
  Location: ${userProfile.location}
  Water: ${userProfile.waterSource}
  Involvement: ${userProfile.involvement}

  Output Format:
  **Overall Risk:** [Low/Medium/High]

  **Reasons:**
  - [Reason 1]
  - [Reason 2]
  - [Reason 3]
  `;
  return sendMessageToGemini(prompt, [], userProfile);
};

export const getCostAnalysis = async (userProfile: UserProfile): Promise<string> => {
  const prompt = `
  Analyze budget for a 1-acre beginner farm.
  User Budget: ${userProfile.budget}

  Task: Compare estimated costs (Seeds, Fertilizer, Water, Labor) vs their budget.
  State if it is "Within Budget", "Slightly High", or "High Risk".
  Provide a short helpful comment.
  `;
  return sendMessageToGemini(prompt, [], userProfile);
};

import React, { useState, useEffect } from 'react';
