import Button from './Button';

interface MyPlanProps {
  userProfile: UserProfile;
}

type ViewState = 'menu' | 'crops' | 'calendar' | 'costs' | 'risk';

const MyPlan: React.FC<MyPlanProps> = ({ userProfile }) => {
