  const [cropRecs, setCropRecs] = useState<string>('');
  const [loadingCrops, setLoadingCrops] = useState(false);

  // --- TASKS STATE ---
  const [tasks, setTasks] = useState<Task[]>([
    { id: '1', week: 1, title: 'Soil Preparation', status: 'completed', description: 'Clear weeds and plow the land lightly to aerate the soil.' },
    { id: '2', week: 1, title: 'Soil Testing', status: 'pending', description: 'Take a sample from 5 spots, mix them, and observe texture/color.' },
    { id: '3', week: 2, title: 'Purchase Seeds', status: 'pending', description: 'Buy organic seeds for Spinach/Fenugreek from a certified local vendor.' },
  ]);
  const [newTaskTitle, setNewTaskTitle] = useState('');
  const [expandedTaskId, setExpandedTaskId] = useState<string | null>(null);

  // --- ANALYSIS STATE ---
  const [riskAnalysis, setRiskAnalysis] = useState<string>('');
  const [loadingRisk, setLoadingRisk] = useState(false);
  const [costAnalysis, setCostAnalysis] = useState<string>('');
  const [loadingCost, setLoadingCost] = useState(false);

  // --- MOCK CHART DATA ---
  const costData = [
    { name: 'Seeds', value: 2000 },
    { name: 'Fertilizer', value: 4000 },
    { name: 'Labor', value: 5000 },
    { name: 'Water/Elec', value: 3000 },
  ];
