  const COLORS = ['#16a34a', '#ca8a04', '#ea580c', '#3b82f6'];

  // --- CALENDAR HELPERS ---
  const daysInMonth = 30; // Simplified
  const currentDay = 12; // Mock current day
  const taskDays = [5, 12, 18, 25]; // Mock days with tasks

  // --- EFFECTS ---
  useEffect(() => {
    if (view === 'risk' && !riskAnalysis && !loadingRisk) {
      setLoadingRisk(true);
      getRiskAssessment(userProfile).then(res => {
        setRiskAnalysis(res);
        setLoadingRisk(false);
      });
    }
    if (view === 'costs' && !costAnalysis && !loadingCost) {
      setLoadingCost(true);
      getCostAnalysis(userProfile).then(res => {
        setCostAnalysis(res);
        setLoadingCost(false);
      });
    }
  }, [view, userProfile, riskAnalysis, costAnalysis, loadingRisk, loadingCost]);

  // --- HANDLERS ---
  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setSoilImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const fetchCrops = async () => {
    setLoadingCrops(true);
    const result = await getCropRecommendations(userProfile, soilType, moisture, soilImage || undefined);
    setCropRecs(result);
    setLoadingCrops(false);
  };

  const addTask = () => {
    if (!newTaskTitle.trim()) return;
    const newTask: Task = {
      id: Date.now().toString(),
      week: 1,
      title: newTaskTitle,
      description: 'Custom user task.',
      status: 'pending',
      isCustom: true
    };
    setTasks([...tasks, newTask]);
    setNewTaskTitle('');
  };

  const toggleTaskStatus = (id: string) => {
    setTasks(tasks.map(t => t.id === id ? { ...t, status: t.status === 'completed' ? 'pending' : 'completed' } : t));
  };

  // --- RENDERERS ---

  const renderMenu = () => (
    <div className="grid grid-cols-2 gap-4 p-4">
      <div onClick={() => setView('crops')} className="bg-white p-5 rounded-2xl border border-gray-100 shadow-sm flex flex-col items-center text-center gap-3 active:scale-95 transition-all cursor-pointer">
        <div className="w-12 h-12 bg-green-100 rounded-full flex items-center justify-center text-green-600"><Sprout /></div>
        <span className="font-semibold text-gray-900">My Current Crops</span>
      </div>
      <div onClick={() => setView('calendar')} className="bg-white p-5 rounded-2xl border border-gray-100 shadow-sm flex flex-col items-center text-center gap-3 active:scale-95 transition-all cursor-pointer">
        <div className="w-12 h-12 bg-blue-100 rounded-full flex items-center justify-center text-blue-600"><CalendarIcon /></div>
        <span className="font-semibold text-gray-900">Calendar & Tasks</span>
      </div>
      <div onClick={() => setView('costs')} className="bg-white p-5 rounded-2xl border border-gray-100 shadow-sm flex flex-col items-center text-center gap-3 active:scale-95 transition-all cursor-pointer">
        <div className="w-12 h-12 bg-amber-100 rounded-full flex items-center justify-center text-amber-600"><Coins /></div>
        <span className="font-semibold text-gray-900">Cost Summary</span>
      </div>
      <div onClick={() => setView('risk')} className="bg-white p-5 rounded-2xl border border-gray-100 shadow-sm flex flex-col items-center text-center gap-3 active:scale-95 transition-all cursor-pointer">
        <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center text-red-600"><ShieldAlert /></div>
        <span className="font-semibold text-gray-900">Risk Level</span>
      </div>
    </div>
  );

  const renderCrops = () => (
    <div className="p-4 space-y-6">
      <div className="bg-white p-4 rounded-xl border border-gray-200">
        <h3 className="font-bold text-gray-800 mb-4">Soil & Conditions</h3>

        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Soil Type</label>
            <select 
              value={soilType} 
              onChange={(e) => setSoilType(e.target.value as SoilType)}
              className="w-full p-3 border border-gray-300 rounded-lg bg-gray-50 text-gray-900"
            >
              <option value="Loamy">Loamy (Balanced)</option>
              <option value="Black">Black (Clay-rich)</option>
              <option value="Red">Red (Iron-rich)</option>
              <option value="Sandy">Sandy (Drains fast)</option>
              <option value="Clay">Clay (Holds water)</option>
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Moisture Level</label>
            <select 
              value={moisture} 
              onChange={(e) => setMoisture(e.target.value as MoistureLevel)}
              className="w-full p-3 border border-gray-300 rounded-lg bg-gray-50 text-gray-900"
            >
              <option value="Low">Low (Dry)</option>
              <option value="Medium">Medium (Moist)</option>
              <option value="High">High (Wet)</option>
            </select>
          </div>

          <div>
             <label className="block text-sm font-medium text-gray-700 mb-1">Upload Soil Photo (Assisted Analysis)</label>
             <div className="flex items-center gap-2">
                <label className="flex-1 cursor-pointer bg-gray-50 border border-gray-300 border-dashed rounded-lg p-3 text-center text-gray-500 hover:bg-gray-100 transition-colors">
                  <span className="flex items-center justify-center gap-2 text-sm">
                    <ImageIcon className="w-4 h-4"/> {soilImage ? 'Change Photo' : 'Take/Upload Photo'}
                  </span>
                  <input type="file" accept="image/*" className="hidden" onChange={handleImageSelect} />
                </label>
                {soilImage && (
                  <div className="relative w-12 h-12 flex-shrink-0">
                    <img src={soilImage} className="w-full h-full object-cover rounded-md" alt="Soil" />
                    <button onClick={() => setSoilImage(null)} className="absolute -top-1 -right-1 bg-red-500 text-white rounded-full p-0.5"><X className="w-3 h-3"/></button>
                  </div>
                )}
             </div>
             {soilImage && <p className="text-xs text-blue-600 mt-2 italic">Based on visual cues only. Not 100% accurate.</p>}
          </div>

          <Button fullWidth onClick={fetchCrops} disabled={loadingCrops}>
            {loadingCrops ? <><Loader2 className="animate-spin" /> Analyzing...</> : 'Suggest Beginner Crops'}
          </Button>
        </div>
      </div>

      {cropRecs && (
        <div className="bg-green-50 p-4 rounded-xl border border-green-200 animate-in fade-in slide-in-from-bottom-4">
           <h3 className="font-bold text-green-800 mb-2 flex items-center gap-2">
             <Sprout className="w-5 h-5" /> Recommended Crops
           </h3>
           <div className="whitespace-pre-wrap text-sm text-green-900 leading-relaxed">
             {cropRecs}
           </div>
        </div>
      )}
    </div>
  );

  const renderCalendar = () => (
    <div className="p-4 space-y-6">
      {/* Calendar Widget */}
      <div className="bg-white p-4 rounded-xl border border-gray-200 shadow-sm">
        <div className="flex justify-between items-center mb-4">
          <h3 className="font-bold text-gray-800">October 2023</h3>
          <div className="flex gap-2">
            <button className="p-1 text-gray-500 hover:bg-gray-100 rounded"><ChevronLeft className="w-5 h-5"/></button>
            <button className="p-1 text-gray-500 hover:bg-gray-100 rounded"><ChevronRight className="w-5 h-5"/></button>
          </div>
        </div>
        <div className="grid grid-cols-7 gap-1 text-center mb-2">
          {['S','M','T','W','T','F','S'].map(d => <div key={d} className="text-xs font-semibold text-gray-400">{d}</div>)}
        </div>
        <div className="grid grid-cols-7 gap-1">
          {Array.from({length: daysInMonth}).map((_, i) => {
            const day = i + 1;
            const hasTask = taskDays.includes(day);
            const isToday = day === currentDay;
            return (
              <div 
                key={day} 
                className={`h-9 flex flex-col items-center justify-center rounded-lg text-sm cursor-pointer relative
                  ${isToday ? 'bg-green-600 text-white font-bold' : 'hover:bg-gray-50 text-gray-700'}
                `}
              >
                {day}
                {hasTask && !isToday && <div className="w-1 h-1 bg-green-500 rounded-full mt-0.5"></div>}
                {hasTask && isToday && <div className="w-1 h-1 bg-white rounded-full mt-0.5"></div>}
              </div>
            );
          })}
        </div>
      </div>

      {/* Task List */}
      <div className="space-y-4">
        <div className="flex gap-2 mb-2">
          <input 
            type="text" 
            placeholder="Add custom task..." 
            className="flex-1 p-3 border border-gray-300 rounded-lg text-sm text-gray-900 focus:ring-2 focus:ring-green-500 outline-none"
            value={newTaskTitle}
            onChange={(e) => setNewTaskTitle(e.target.value)}
          />
          <button onClick={addTask} className="bg-gray-800 text-white p-2 rounded-lg hover:bg-black"><Plus className="w-5 h-5"/></button>
        </div>

        <div className="space-y-3">
          {tasks.map((task) => (
            <div key={task.id} className="bg-white p-3 rounded-xl border border-gray-200 shadow-sm">
              <div className="flex items-start gap-3">
                <button onClick={() => toggleTaskStatus(task.id)} className="mt-0.5">
                  {task.status === 'completed' 
                    ? <CheckCircle2 className="text-green-600 w-5 h-5" /> 
                    : <Circle className="text-gray-300 w-5 h-5" />
                  }
                </button>
                <div className="flex-1">
                  <div className="flex justify-between items-start">
                     <h4 className={`text-sm font-semibold ${task.status === 'completed' ? 'text-gray-400 line-through' : 'text-gray-900'}`}>
                      {task.title}
                    </h4>
                    <span className="text-[10px] bg-gray-100 px-2 py-0.5 rounded text-gray-500">Wk {task.week}</span>
                  </div>

                  {expandedTaskId === task.id && (
                    <p className="text-xs text-gray-600 mt-2 bg-gray-50 p-2 rounded">
                      {task.description}
                    </p>
                  )}

                  <button 
                    onClick={() => setExpandedTaskId(expandedTaskId === task.id ? null : task.id)}
                    className="text-xs text-blue-600 font-medium mt-1 flex items-center gap-1"
                  >
                    {expandedTaskId === task.id ? 'Hide Guide' : 'View Guide'} 
                    {expandedTaskId === task.id ? <ChevronUp className="w-3 h-3"/> : <ChevronDown className="w-3 h-3"/>}
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );

  const renderCosts = () => (
    <div className="p-4 space-y-6">
      <div className="bg-white p-5 rounded-xl border border-gray-200 shadow-sm">
        <h3 className="font-bold text-gray-800 mb-2">Estimated Breakdown</h3>
        <p className="text-xs text-gray-500 mb-4">Note: These are rough estimates. Prices may vary by market.</p>

        <div className="h-56 w-full">
          <ResponsiveContainer width="100%" height="100%">
            <PieChart>
              <Pie
                data={costData}
                cx="50%"
                cy="50%"
                innerRadius={50}
                outerRadius={70}
                paddingAngle={5}
                dataKey="value"
              >
                {costData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                ))}
              </Pie>
              <RechartsTooltip formatter={(value) => `₹${value}`} />
              <Legend wrapperStyle={{fontSize: '12px'}} />
            </PieChart>
          </ResponsiveContainer>
        </div>

        <div className="mt-4 pt-4 border-t border-gray-100">
           <div className="flex justify-between items-center mb-1">
             <span className="text-sm text-gray-600">Total Est. Cost</span>
             <span className="text-lg font-bold text-gray-900">₹14,000</span>
           </div>

           <div className="mt-4">
             {loadingCost ? (
                <div className="text-center text-sm text-gray-500 py-2"><Loader2 className="w-4 h-4 animate-spin inline mr-2"/> Analyzing your budget...</div>
             ) : (
                <div className="bg-blue-50 text-blue-800 p-3 rounded-lg text-sm whitespace-pre-wrap">
                  {costAnalysis || "Analysis unavailable."}
                </div>
             )}
           </div>
        </div>
      </div>
    </div>
  );

  const renderRisk = () => (
    <div className="p-4 space-y-6">
      {loadingRisk ? (
        <div className="text-center py-10">
          <Loader2 className="w-8 h-8 animate-spin text-green-600 mx-auto mb-3" />
          <p className="text-gray-500">Assessing your farm's risk factors...</p>
        </div>
      ) : (
        <div className="space-y-4">
          <div className="bg-white p-6 rounded-xl border border-gray-200 text-center shadow-sm">
            <div className="inline-flex items-center justify-center w-20 h-20 rounded-full bg-amber-100 text-amber-600 mb-4">
                <AlertCircle className="w-10 h-10" />
            </div>
            <div className="whitespace-pre-wrap text-left text-sm text-gray-700 leading-relaxed">
              {riskAnalysis || "Risk assessment unavailable."}
            </div>
          </div>
          <div className="text-center">
             <button onClick={() => { setLoadingRisk(false); setRiskAnalysis(''); }} className="text-sm text-green-600 flex items-center justify-center gap-1 w-full">
               <RefreshCw className="w-3 h-3"/> Refresh Assessment
             </button>
          </div>
        </div>
      )}
    </div>
  );

  return (
    <div className="flex flex-col h-full bg-gray-50 pb-20">
      <div className="bg-white p-4 border-b border-gray-200 sticky top-0 z-10 flex items-center gap-3">
        {view !== 'menu' && (
          <button onClick={() => setView('menu')} className="p-1 rounded-full hover:bg-gray-100">
            <ArrowLeft className="w-6 h-6 text-gray-600" />
          </button>
        )}
        <h2 className="text-xl font-bold text-gray-800">
          {view === 'menu' && 'Farm Dashboard'}
          {view === 'crops' && 'Crop Advisor'}
          {view === 'calendar' && 'Tasks & Guide'}
          {view === 'costs' && 'Cost Analysis'}
          {view === 'risk' && 'Risk Assessment'}
        </h2>
      </div>

      <div className="flex-1 overflow-y-auto">
        {view === 'menu' && renderMenu()}
        {view === 'crops' && renderCrops()}
        {view === 'calendar' && renderCalendar()}
        {view === 'costs' && renderCosts()}
        {view === 'risk' && renderRisk()}
      </div>
    </div>
  );
};

export default MyPlan;

import React, { useState } from 'react';
import { UserProfile, Land } from '../types';
import { User, MapPin, Plus, CreditCard, Settings, Globe, X, Check, Edit2, LogOut } from 'lucide-react';
import Button from './Button';

interface ProfileProps {
  userProfile: UserProfile;
  onLogout?: () => void;
  onUpdateProfile?: (updates: Partial<UserProfile>) => void;
}

const Profile: React.FC<ProfileProps> = ({ userProfile, onLogout, onUpdateProfile }) => {
  const [lands, setLands] = useState<Land[]>(
    userProfile.lands || [{ id: '1', name: 'Main Farm', size: userProfile.landSize, location: userProfile.location }]
  );

  // Modals state
  const [showAddLand, setShowAddLand] = useState(false);
  const [showEditLand, setShowEditLand] = useState<Land | null>(null);
  const [showSubscription, setShowSubscription] = useState(false);

  // Temp form state
  const [tempLand, setTempLand] = useState<Partial<Land>>({});

  const handleAddLand = () => {
    if (tempLand.name && tempLand.location && tempLand.size) {
      const newLand: Land = {
        id: Date.now().toString(),
        name: tempLand.name,
        location: tempLand.location,
        size: tempLand.size
      };
      const updatedLands = [...lands, newLand];
      setLands(updatedLands);
      if (onUpdateProfile) onUpdateProfile({ lands: updatedLands });
      setShowAddLand(false);
      setTempLand({});
    }
  };

  const handleUpdateLand = () => {
    if (showEditLand && tempLand.name) {
      const updatedLands = lands.map(l => l.id === showEditLand.id ? { ...l, ...tempLand } as Land : l);
      setLands(updatedLands);
      if (onUpdateProfile) onUpdateProfile({ lands: updatedLands });
      setShowEditLand(null);
      setTempLand({});
    }
  };

  const handleLanguageChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    if (onUpdateProfile) {
      onUpdateProfile({ language: e.target.value as any });
    }
  };

  return (
    <div className="p-4 bg-gray-50 min-h-full pb-20 space-y-6">
      <h1 className="text-2xl font-bold text-gray-900">My Profile</h1>

      {/* Header Card */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden relative">
        <div className="bg-gradient-to-r from-green-600 to-green-500 h-24"></div>
        <div className="px-4 pb-4">
           <div className="relative -mt-10 mb-3">
            <div className="w-20 h-20 bg-white rounded-full p-1 shadow-sm">
              <div className="w-full h-full bg-gray-100 rounded-full flex items-center justify-center text-gray-500">
                <User className="w-10 h-10" />
              </div>
            </div>
           </div>
           <h2 className="text-xl font-bold text-gray-800">{userProfile.name}</h2>
           <div className="flex gap-2 mt-1">
             <span className="bg-green-100 text-green-800 text-xs px-2 py-1 rounded-full font-medium">
                {userProfile.experienceLevel}
             </span>
             <span className="bg-blue-100 text-blue-800 text-xs px-2 py-1 rounded-full font-medium">
                {userProfile.language}
             </span>
           </div>
        </div>
      </div>

      {/* My Lands */}
      <div>
        <div className="flex justify-between items-center mb-3 px-1">
            <h3 className="font-bold text-gray-700">My Lands</h3>
            <button 
              onClick={() => setShowAddLand(true)}
              className="text-green-600 text-sm font-medium flex items-center gap-1"
            >
                <Plus className="w-4 h-4"/> Add
            </button>
        </div>
        <div className="space-y-3">
            {lands.map(land => (
                <div key={land.id} className="bg-white p-4 rounded-xl border border-gray-200 flex justify-between items-center">
                    <div>
                        <h4 className="font-semibold text-gray-900">{land.name}</h4>
                        <div className="flex items-center gap-3 text-sm text-gray-500 mt-1">
                            <span className="flex items-center gap-1"><MapPin className="w-3 h-3"/> {land.location}</span>
                            <span className="w-1 h-1 bg-gray-300 rounded-full"></span>
                            <span>{land.size}</span>
                        </div>
                    </div>
                    <button 
                      onClick={() => { setShowEditLand(land); setTempLand(land); }}
                      className="text-gray-400 hover:text-green-600"
                    >
                      <Edit2 className="w-4 h-4"/>
                    </button>
                </div>
            ))}
        </div>
      </div>

      {/* Subscription */}
      <div>
         <h3 className="font-bold text-gray-700 mb-3 px-1">Subscription</h3>
         <div 
           onClick={() => setShowSubscription(true)}
           className="bg-gradient-to-br from-gray-900 to-gray-800 rounded-xl p-5 text-white shadow-lg cursor-pointer active:scale-95 transition-transform"
         >
            <div className="flex justify-between items-start mb-4">
                <div>
                    <div className="text-sm text-gray-300 font-medium">Current Plan</div>
                    <div className="text-2xl font-bold">Free Tier</div>
                </div>
                <CreditCard className="w-6 h-6 text-yellow-400" />
            </div>
            <p className="text-sm text-gray-400 mb-4">Upgrade to access advanced crop disease detection and expert calls.</p>
            <div className="inline-block bg-white/10 px-3 py-1 rounded-full text-xs font-medium border border-white/10">
               View Upgrade Options
            </div>
         </div>
      </div>

      {/* Settings */}
      <div>
         <h3 className="font-bold text-gray-700 mb-3 px-1">Settings</h3>
         <div className="bg-white rounded-xl border border-gray-200 divide-y divide-gray-100">
             <div className="p-4 flex items-center justify-between">
                <div className="flex items-center gap-3">
                    <div className="bg-blue-50 p-2 rounded-lg text-blue-600"><Globe className="w-5 h-5"/></div>
                    <span className="text-sm font-medium text-gray-700">App Language</span>
                </div>
                <select 
                  className="text-sm bg-transparent text-right font-medium text-gray-600 outline-none cursor-pointer" 
                  value={userProfile.language}
                  onChange={handleLanguageChange}
                >
                    <option value="English">English</option>
                    <option value="Hindi">Hindi</option>
                    <option value="Tamil">Tamil</option>
                    <option value="Telugu">Telugu</option>
                    <option value="Kannada">Kannada</option>
                </select>
             </div>
             <div className="p-4 flex items-center justify-between">
                <div className="flex items-center gap-3">
                    <div className="bg-gray-50 p-2 rounded-lg text-gray-600"><Settings className="w-5 h-5"/></div>
                    <span className="text-sm font-medium text-gray-700">Notifications</span>
                </div>
                <div className="w-10 h-5 bg-green-500 rounded-full relative cursor-pointer">
                    <div className="absolute right-1 top-1 w-3 h-3 bg-white rounded-full shadow-sm"></div>
                </div>
             </div>
         </div>
      </div>

      <div className="mt-8 text-center pb-6">
         <button 
           onClick={onLogout}
           className="text-red-500 text-sm font-medium hover:bg-red-50 px-4 py-2 rounded-lg transition-colors flex items-center justify-center gap-2 w-full"
         >
           <LogOut className="w-4 h-4"/> Log Out
         </button>
      </div>

      {/* --- MODALS --- */}

      {/* Add Land Modal */}
      {showAddLand && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl w-full max-w-sm p-6">
            <h3 className="text-lg font-bold mb-4">Add New Land</h3>
            <div className="space-y-3">
              <input 
                placeholder="Land Name (e.g. Riverside Plot)" 
                className="w-full p-3 border rounded-xl text-gray-900"
                onChange={(e) => setTempLand({...tempLand, name: e.target.value})}
              />
              <input 
                placeholder="Location" 
                className="w-full p-3 border rounded-xl text-gray-900"
                onChange={(e) => setTempLand({...tempLand, location: e.target.value})}
              />
               <input 
                placeholder="Size (e.g. 2 Acres)" 
                className="w-full p-3 border rounded-xl text-gray-900"
                onChange={(e) => setTempLand({...tempLand, size: e.target.value})}
              />
            </div>
            <div className="flex gap-2 mt-6">
              <Button variant="outline" fullWidth onClick={() => setShowAddLand(false)}>Cancel</Button>
              <Button fullWidth onClick={handleAddLand}>Save</Button>
            </div>
          </div>
        </div>
      )}

      {/* Edit Land Modal */}
      {showEditLand && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl w-full max-w-sm p-6">
            <h3 className="text-lg font-bold mb-4">Edit Land</h3>
            <div className="space-y-3">
              <input 
                defaultValue={showEditLand.name}
                className="w-full p-3 border rounded-xl text-gray-900"
                onChange={(e) => setTempLand({...tempLand, name: e.target.value})}
              />
              <input 
                defaultValue={showEditLand.location}
                className="w-full p-3 border rounded-xl text-gray-900"
                onChange={(e) => setTempLand({...tempLand, location: e.target.value})}
              />
               <input 
                defaultValue={showEditLand.size}
                className="w-full p-3 border rounded-xl text-gray-900"
                onChange={(e) => setTempLand({...tempLand, size: e.target.value})}
              />
            </div>
            <div className="flex gap-2 mt-6">
              <Button variant="outline" fullWidth onClick={() => setShowEditLand(null)}>Cancel</Button>
              <Button fullWidth onClick={handleUpdateLand}>Update</Button>
            </div>
          </div>
        </div>
      )}

