                className="w-full p-3 bg-white border border-gray-300 rounded-xl text-gray-900 focus:ring-2 focus:ring-green-500 outline-none"
                value={profile.language || ''}
                onChange={(e) => updateProfile('language', e.target.value)}
              >
                <option value="English">English</option>
                <option value="Hindi">Hindi</option>
                <option value="Tamil">Tamil</option>
                <option value="Telugu">Telugu</option>
                <option value="Kannada">Kannada</option>
              </select>
            </div>
          </div>
        )}

        {step === 2 && (
          <div className="space-y-4">
             <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Location (State/District)</label>
              <div className="relative flex gap-2">
                <div className="relative flex-1">
                   <MapPin className="absolute left-3 top-3.5 h-5 w-5 text-gray-400" />
                   <input 
                    type="text" 
                    className="w-full pl-10 p-3 bg-white border border-gray-300 rounded-xl text-gray-900 placeholder-gray-400 focus:ring-2 focus:ring-green-500 outline-none"
                    placeholder="e.g. Pune, Maharashtra"
                    value={profile.location || ''}
                    onChange={(e) => updateProfile('location', e.target.value)}
                  />
                </div>
                <button 
                  onClick={detectLocation}
                  disabled={isLocating}
                  className="bg-green-50 p-3 rounded-xl border border-green-200 text-green-700 hover:bg-green-100"
                >
                  {isLocating ? <Loader2 className="w-5 h-5 animate-spin" /> : <LocateFixed className="w-5 h-5" />}
                </button>
              </div>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Water Source</label>
              <div className="grid grid-cols-2 gap-3">
                {['Borewell', 'Canal', 'Rain', 'Unsure'].map((opt) => (
                  <button
                    key={opt}
                    onClick={() => updateProfile('waterSource', opt)}
                    className={`p-3 rounded-xl border text-sm font-medium transition-colors ${
                      profile.waterSource === opt 
                      ? 'border-green-600 bg-green-50 text-green-700' 
                      : 'border-gray-200 text-gray-600 hover:bg-gray-50'
                    }`}
                  >
                    {opt}
                  </button>
                ))}
              </div>
            </div>
            <div>
               <label className="block text-sm font-medium text-gray-700 mb-1">Total Land Size</label>
               <input 
                type="text" 
                className="w-full p-3 bg-white border border-gray-300 rounded-xl text-gray-900 placeholder-gray-400 focus:ring-2 focus:ring-green-500 outline-none"
                placeholder="e.g. 2 Acres"
                value={profile.landSize || ''}
                onChange={(e) => updateProfile('landSize', e.target.value)}
              />
            </div>
          </div>
        )}

        {step === 3 && (
          <div className="space-y-4">
             <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Primary Goal</label>
              <select 
                className="w-full p-3 bg-white border border-gray-300 rounded-xl text-gray-900 focus:ring-2 focus:ring-green-500 outline-none"
                value={profile.goal || ''}
                onChange={(e) => updateProfile('goal', e.target.value)}
              >
                <option value="">Select Goal</option>
                <option value="Income">Income (Profit focus)</option>
                <option value="Hobby">Hobby / Relaxation</option>
                <option value="Organic Food">Home Consumption</option>
                <option value="Land Productivity">Keep Land Active</option>
              </select>
            </div>
             <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Budget Range (₹)</label>
              <div className="relative">
                <IndianRupee className="absolute left-3 top-3.5 h-5 w-5 text-gray-400" />
                <input 
                  type="text" 
                  className="w-full pl-10 p-3 bg-white border border-gray-300 rounded-xl text-gray-900 placeholder-gray-400 focus:ring-2 focus:ring-green-500 outline-none"
                  placeholder="e.g. 50,000 - 1 Lakh"
                  value={profile.budget || ''}
                  onChange={(e) => updateProfile('budget', e.target.value)}
                />
              </div>
            </div>
          </div>
        )}

        {step === 4 && (
          <div className="space-y-4">
             <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">How involved can you be?</label>
              <div className="grid grid-cols-1 gap-3">
                {[
                  { id: 'Daily', label: t.daily, desc: 'Best for vegetables/flowers' },
                  { id: 'Weekend', label: t.weekend, desc: 'Good for trees/hardy crops' },
                  { id: 'Hired Help', label: t.hired, desc: 'Needs good management' },
                ].map((opt) => (
                  <button
                    key={opt.id}
                    onClick={() => updateProfile('involvement', opt.id)}
                    className={`p-4 rounded-xl border text-left transition-colors ${
                      profile.involvement === opt.id 
                      ? 'border-green-600 bg-green-50' 
                      : 'border-gray-200 hover:bg-gray-50'
                    }`}
                  >
                    <div className={`font-semibold ${profile.involvement === opt.id ? 'text-green-800' : 'text-gray-800'}`}>{opt.label}</div>
                    <div className="text-xs text-gray-500">{opt.desc}</div>
                  </button>
                ))}
              </div>
            </div>
          </div>
        )}
      </div>

      <div className="w-full pt-4">
        {step < 4 ? (
          <Button 
            fullWidth 
            onClick={handleNext} 
            disabled={
              (step === 1 && (!profile.name || !profile.language)) ||
              (step === 2 && (!profile.location || !profile.waterSource)) ||
              (step === 3 && (!profile.goal || !profile.budget))
            }
          >
            Next Step
          </Button>
        ) : (
          <Button 
            fullWidth 
            onClick={finish}
            disabled={!profile.involvement}
          >
            Create My Farm Plan
          </Button>
        )}
      </div>
    </div>
  );
};

export default Onboarding;

import React from 'react';
import { Home as HomeIcon, ClipboardList, MessageCircle, User } from 'lucide-react';
